INSERT INTO `faqs` (`id`, `question`, `answer`, `sort_order`, `is_active`, `created_at`, `updated_at`) VALUES
('1', '{\"ar\":\"ما هي المناطق التي تغطونها؟\",\"en\":\"Which areas do you cover?\"}', '{\"ar\":\"نغطي جميع محافظات الكويت الست مع تركيز أكبر على السالمية وحولي ومدينة الكويت والجابرية.\",\"en\":\"We cover all six governorates of Kuwait, with a focus on Salmiya, Hawally, Kuwait City and Jabriya.\"}', '0', '1', '2026-08-09 15:24:37', '2026-08-09 15:24:37'),
('2', '{\"ar\":\"كم تستغرق عملية المعاينة؟\",\"en\":\"How long does a viewing take?\"}', '{\"ar\":\"يتم ترتيب المعاينة خلال ٢٤ إلى ٤٨ ساعة من طلبك حسب توفر المالك.\",\"en\":\"A viewing is arranged within 24 to 48 hours of your request, subject to owner availability.\"}', '1', '1', '2026-08-09 15:24:37', '2026-08-09 15:24:37'),
('3', '{\"ar\":\"هل توجد عمولة على المستأجر؟\",\"en\":\"Is there a commission for tenants?\"}', '{\"ar\":\"العمولة تعادل إيجار نصف شهر لعقود الإيجار السنوية، وتُوضّح قبل توقيع العقد.\",\"en\":\"The commission equals half a month rent for yearly contracts and is disclosed before signing.\"}', '2', '1', '2026-08-09 15:24:37', '2026-08-09 15:24:37'),
('4', '{\"ar\":\"هل يمكنني عرض عقاري لديكم؟\",\"en\":\"Can I list my property with you?\"}', '{\"ar\":\"نعم، أرسل بيانات العقار من صفحة «تواصل معنا» وسيتواصل معك مسؤول العقار لتقييمه مجانًا.\",\"en\":\"Yes — send your property details via the contact page and an agent will contact you for a free valuation.\"}', '3', '1', '2026-08-09 15:24:37', '2026-08-09 15:24:37'),
('5', '{\"ar\":\"هل الأسعار المعروضة نهائية؟\",\"en\":\"Are the listed prices final?\"}', '{\"ar\":\"الأسعار استرشادية وقابلة للتفاوض في معظم الحالات حسب رغبة المالك.\",\"en\":\"Prices are indicative and negotiable in most cases, depending on the owner.\"}', '4', '1', '2026-08-09 15:24:37', '2026-08-09 15:24:37'),
('6', '{\"ar\":\"هل تقدّمون خدمة إدارة الأملاك؟\",\"en\":\"Do you offer property management?\"}', '{\"ar\":\"نعم، نوفّر إدارة كاملة تشمل التحصيل والصيانة ومتابعة العقود.\",\"en\":\"Yes — full management including rent collection, maintenance and contract follow-up.\"}', '5', '1', '2026-08-09 15:24:37', '2026-08-09 15:24:37');
