INSERT INTO `page_sections` (`id`, `page_id`, `key`, `sort_order`, `is_visible`, `content`, `created_at`, `updated_at`) VALUES
('10', '2', 'values', '2', '1', '{\"ar\":{\"items\":[{\"icon\":\"Handshake\",\"title\":{\"ar\":\"الشفافية\",\"en\":\"Transparency\"},\"description\":{\"ar\":\"نعرض العقار كما هو، بلا مبالغة أو معلومات ناقصة.\",\"en\":\"We present the property as it is — no exaggeration, no missing information.\"}},{\"icon\":\"Target\",\"title\":{\"ar\":\"الاحترافية\",\"en\":\"Professionalism\"},\"description\":{\"ar\":\"إجراءات موثّقة ومتابعة منظّمة لكل صفقة.\",\"en\":\"Documented procedures and organised follow-up for every deal.\"}},{\"icon\":\"Heart\",\"title\":{\"ar\":\"رضا العميل\",\"en\":\"Client Satisfaction\"},\"description\":{\"ar\":\"نقيس نجاحنا بعودة عملائنا وترشيحهم لنا.\",\"en\":\"We measure success by returning clients and their referrals.\"}}],\"title\":\"قيمنا\",\"subtitle\":\"ثلاث قيم تحكم كل تعامل داخل علم العقارية.\"},\"en\":{\"items\":[{\"icon\":\"Handshake\",\"title\":{\"ar\":\"الشفافية\",\"en\":\"Transparency\"},\"description\":{\"ar\":\"نعرض العقار كما هو، بلا مبالغة أو معلومات ناقصة.\",\"en\":\"We present the property as it is — no exaggeration, no missing information.\"}},{\"icon\":\"Target\",\"title\":{\"ar\":\"الاحترافية\",\"en\":\"Professionalism\"},\"description\":{\"ar\":\"إجراءات موثّقة ومتابعة منظّمة لكل صفقة.\",\"en\":\"Documented procedures and organised follow-up for every deal.\"}},{\"icon\":\"Heart\",\"title\":{\"ar\":\"رضا العميل\",\"en\":\"Client Satisfaction\"},\"description\":{\"ar\":\"نقيس نجاحنا بعودة عملائنا وترشيحهم لنا.\",\"en\":\"We measure success by returning clients and their referrals.\"}}],\"title\":\"Our Values\",\"subtitle\":\"Three values that govern every interaction at Alam.\"}}', '2026-08-09 15:19:09', '2026-08-09 15:24:37'),
('12', '4', 'header', '0', '1', '{\"ar\":{\"title\":\"العروض العقارية\",\"description\":\"عروض محدودة على وحدات مختارة — تواصل معنا قبل انتهاء المدة.\"},\"en\":{\"title\":\"Property Offers\",\"description\":\"Limited offers on selected units — contact us before they expire.\"}}', '2026-08-09 15:24:37', '2026-08-09 15:24:37'),
('13', '3', 'header', '0', '1', '{\"ar\":{\"title\":\"كل العقارات\",\"description\":\"استخدم الفلاتر للوصول إلى العقار المناسب لك بسرعة.\"},\"en\":{\"title\":\"All Properties\",\"description\":\"Use the filters to quickly find the property that suits you.\"}}', '2026-08-09 15:24:37', '2026-08-09 15:24:37'),
('14', '9', 'body', '0', '1', '{\"ar\":{\"body\":\"<h3>مقدمة</h3><p>باستخدامك موقع علم العقارية فإنك توافق على الشروط الواردة في هذه الصفحة.</p><h3>استخدام المحتوى</h3><p>جميع بيانات العقارات المعروضة مملوكة لعلم العقارية ولا يجوز إعادة نشرها دون إذن كتابي.</p><h3>دقة المعلومات</h3><p>نبذل جهدنا لتحديث الأسعار والحالة بشكل مستمر، وقد تتغير بيانات العقار دون إشعار مسبق.</p>\"},\"en\":{\"body\":\"<h3>Introduction</h3><p>By using the Alam Real Estate website you agree to the terms on this page.</p><h3>Use of Content</h3><p>All property data is owned by Alam Real Estate and may not be republished without written permission.</p><h3>Accuracy</h3><p>We continuously update prices and status; property data may change without prior notice.</p>\"}}', '2026-08-09 15:24:37', '2026-08-09 15:24:37'),
('15', '10', 'body', '0', '1', '{\"ar\":{\"body\":\"<h3>البيانات التي نجمعها</h3><p>نجمع الاسم ورقم الهاتف والبريد الإلكتروني عند إرسال طلب من الموقع فقط.</p><h3>كيف نستخدمها</h3><p>تُستخدم بياناتك للتواصل معك بخصوص طلبك ولا تُشارك مع أي جهة خارجية.</p><h3>حقوقك</h3><p>يمكنك طلب حذف بياناتك في أي وقت عبر صفحة تواصل معنا.</p>\"},\"en\":{\"body\":\"<h3>Data We Collect</h3><p>We collect your name, phone and email only when you submit a request through the site.</p><h3>How We Use It</h3><p>Your data is used to contact you about your request and is never shared with third parties.</p><h3>Your Rights</h3><p>You may request deletion of your data at any time via the contact page.</p>\"}}', '2026-08-09 15:24:37', '2026-08-09 15:24:37'),
('1', '1', 'hero', '0', '1', '{\"ar\":{\"stats\":{\"properties\":\"١٢٠+\",\"clients\":\"٤٥٠+\",\"areas\":\"١٠\"},\"badge\":\"وكيلك العقاري في الكويت\",\"title\":\"ابحث عن بيتك القادم مع علم العقارية\",\"subtitle\":\"شقق · فلل · أراضٍ · مكاتب\",\"description\":\"نساعدك على اختيار العقار المناسب بأفضل سعر، مع فريق متابعة يرافقك من المعاينة حتى توقيع العقد.\"},\"en\":{\"stats\":{\"properties\":\"١٢٠+\",\"clients\":\"٤٥٠+\",\"areas\":\"١٠\"},\"badge\":\"Your real-estate partner in Kuwait\",\"title\":\"Find your next home with Alam Real Estate\",\"subtitle\":\"Apartments · Villas · Land · Offices\",\"description\":\"We help you choose the right property at the best price, with a team that supports you from viewing to signing.\"}}', '2026-08-09 15:19:08', '2026-08-09 15:24:27'),
('2', '1', 'featured', '1', '1', '{\"ar\":{\"title\":\"عقارات مميّزة\",\"description\":\"مجموعة مختارة من أفضل العروض المتاحة حاليًا لدى علم العقارية.\"},\"en\":{\"title\":\"Featured Properties\",\"description\":\"A hand-picked selection of the best offers currently available at Alam.\"}}', '2026-08-09 15:19:09', '2026-08-09 15:24:29'),
('3', '1', 'areas', '2', '1', '{\"ar\":{\"items\":[{\"area_id\":\"3\",\"count\":\"٣٢\",\"collection\":\"area-1\"},{\"area_id\":\"2\",\"count\":\"٢٨\",\"collection\":\"area-2\"},{\"area_id\":\"1\",\"count\":\"٢١\",\"collection\":\"area-3\"},{\"area_id\":\"8\",\"count\":\"١٧\",\"collection\":\"area-4\"}],\"title\":\"أفضل المناطق\",\"description\":\"استعرض العقارات حسب أكثر المناطق طلبًا في الكويت.\"},\"en\":{\"items\":[{\"area_id\":\"3\",\"count\":\"٣٢\",\"collection\":\"area-1\"},{\"area_id\":\"2\",\"count\":\"٢٨\",\"collection\":\"area-2\"},{\"area_id\":\"1\",\"count\":\"٢١\",\"collection\":\"area-3\"},{\"area_id\":\"8\",\"count\":\"١٧\",\"collection\":\"area-4\"}],\"title\":\"Top Areas\",\"description\":\"Browse properties in the most in-demand areas of Kuwait.\"}}', '2026-08-09 15:19:09', '2026-08-09 15:24:35'),
('4', '1', 'videos', '3', '1', '{\"ar\":{\"items\":[1,6,10],\"title\":\"جولات بالفيديو\",\"description\":\"شاهد العقار قبل زيارته من خلال جولة مصوّرة كاملة.\"},\"en\":{\"items\":[1,6,10],\"title\":\"Video Tours\",\"description\":\"See the property before visiting through a full video tour.\"}}', '2026-08-09 15:19:09', '2026-08-09 15:24:35'),
('5', '1', 'why_us', '4', '1', '{\"ar\":{\"items\":[{\"number\":\"٠١\",\"icon\":\"ShieldCheck\",\"title\":{\"ar\":\"موثوقية\",\"en\":\"Trust\"},\"description\":{\"ar\":\"كل عقار موثّق ومعاين من فريقنا قبل عرضه.\",\"en\":\"Every property is documented and inspected by our team before listing.\"}},{\"number\":\"٠٢\",\"icon\":\"Clock\",\"title\":{\"ar\":\"سرعة استجابة\",\"en\":\"Fast Response\"},\"description\":{\"ar\":\"نرد على طلبك خلال ساعة عمل واحدة.\",\"en\":\"We respond to your request within one business hour.\"}},{\"number\":\"٠٣\",\"icon\":\"HandCoins\",\"title\":{\"ar\":\"أسعار عادلة\",\"en\":\"Fair Pricing\"},\"description\":{\"ar\":\"تقييم سعري مبني على بيانات السوق الفعلية.\",\"en\":\"Pricing based on real market data.\"}},{\"number\":\"٠٤\",\"icon\":\"Users\",\"title\":{\"ar\":\"فريق متخصص\",\"en\":\"Expert Team\"},\"description\":{\"ar\":\"مسؤول عقار مخصّص يتابع معك حتى الإغلاق.\",\"en\":\"A dedicated agent follows up with you until closing.\"}}],\"title\":\"لماذا علم العقارية؟\",\"description\":\"أربعة أسباب تجعل عملاءنا يعودون إلينا في كل صفقة.\"},\"en\":{\"items\":[{\"number\":\"٠١\",\"icon\":\"ShieldCheck\",\"title\":{\"ar\":\"موثوقية\",\"en\":\"Trust\"},\"description\":{\"ar\":\"كل عقار موثّق ومعاين من فريقنا قبل عرضه.\",\"en\":\"Every property is documented and inspected by our team before listing.\"}},{\"number\":\"٠٢\",\"icon\":\"Clock\",\"title\":{\"ar\":\"سرعة استجابة\",\"en\":\"Fast Response\"},\"description\":{\"ar\":\"نرد على طلبك خلال ساعة عمل واحدة.\",\"en\":\"We respond to your request within one business hour.\"}},{\"number\":\"٠٣\",\"icon\":\"HandCoins\",\"title\":{\"ar\":\"أسعار عادلة\",\"en\":\"Fair Pricing\"},\"description\":{\"ar\":\"تقييم سعري مبني على بيانات السوق الفعلية.\",\"en\":\"Pricing based on real market data.\"}},{\"number\":\"٠٤\",\"icon\":\"Users\",\"title\":{\"ar\":\"فريق متخصص\",\"en\":\"Expert Team\"},\"description\":{\"ar\":\"مسؤول عقار مخصّص يتابع معك حتى الإغلاق.\",\"en\":\"A dedicated agent follows up with you until closing.\"}}],\"title\":\"Why Alam Real Estate?\",\"description\":\"Four reasons our clients come back for every deal.\"}}', '2026-08-09 15:19:09', '2026-08-09 15:24:35'),
('11', '2', 'team', '3', '1', '{\"ar\":{\"title\":\"فريق العمل\",\"subtitle\":\"تعرّف على مسؤولي العقار المستعدين لمساعدتك.\"},\"en\":{\"title\":\"Our Team\",\"subtitle\":\"Meet the agents ready to help you.\"}}', '2026-08-09 15:19:09', '2026-08-09 15:24:37'),
('6', '1', 'testimonials', '5', '1', '{\"ar\":{\"title\":\"آراء عملائنا\",\"description\":\"تجارب حقيقية لعملاء أتموا صفقاتهم مع علم العقارية.\"},\"en\":{\"title\":\"Client Testimonials\",\"description\":\"Real experiences from clients who closed deals with Alam.\"}}', '2026-08-09 15:19:09', '2026-08-09 15:24:35'),
('7', '1', 'cta', '6', '1', '{\"ar\":{\"badge\":\"ابدأ الآن\",\"title\":\"عندك عقار وتبي تعرضه؟\",\"description\":\"سجّل بياناتك وسيتواصل معك أحد مسؤولي العقار خلال ٢٤ ساعة لتقييم عقارك مجانًا.\"},\"en\":{\"badge\":\"Get started\",\"title\":\"Have a property to list?\",\"description\":\"Leave your details and one of our agents will contact you within 24 hours for a free valuation.\"}}', '2026-08-09 15:19:09', '2026-08-09 15:24:35'),
('8', '2', 'hero', '0', '1', '{\"ar\":{\"badge\":\"من نحن\",\"title\":\"علم العقارية — خبرة كويتية في السوق العقاري\",\"description\":\"شركة كويتية متخصصة في الوساطة والإدارة العقارية، نخدم الأفراد والشركات في جميع محافظات الكويت.\"},\"en\":{\"badge\":\"About us\",\"title\":\"Alam Real Estate — Kuwaiti expertise in property\",\"description\":\"A Kuwaiti company specialised in brokerage and property management, serving individuals and companies across all governorates.\"}}', '2026-08-09 15:19:09', '2026-08-09 15:24:35'),
('9', '2', 'story', '1', '1', '{\"ar\":{\"stats\":[{\"number\":\"١٢+\",\"title\":{\"ar\":\"سنة خبرة\",\"en\":\"Years of experience\"},\"description\":{\"ar\":\"في السوق العقاري الكويتي.\",\"en\":\"In the Kuwaiti real-estate market.\"}},{\"number\":\"٤٥٠+\",\"title\":{\"ar\":\"عميل\",\"en\":\"Clients\"},\"description\":{\"ar\":\"أتمّوا صفقاتهم معنا.\",\"en\":\"Closed their deals with us.\"}},{\"number\":\"١٢٠+\",\"title\":{\"ar\":\"عقار\",\"en\":\"Properties\"},\"description\":{\"ar\":\"معروض حاليًا وبإدارتنا.\",\"en\":\"Currently listed and managed.\"}}],\"title\":\"قصتنا\",\"description\":\"بدأت علم العقارية بمكتب صغير في السالمية، واليوم نُدير محفظة عقارية تغطي محافظات الكويت الست بفريق من مسؤولي العقار المتخصصين. نؤمن أن الصفقة الناجحة تبدأ بمعلومة صادقة وسعر عادل.\"},\"en\":{\"stats\":[{\"number\":\"١٢+\",\"title\":{\"ar\":\"سنة خبرة\",\"en\":\"Years of experience\"},\"description\":{\"ar\":\"في السوق العقاري الكويتي.\",\"en\":\"In the Kuwaiti real-estate market.\"}},{\"number\":\"٤٥٠+\",\"title\":{\"ar\":\"عميل\",\"en\":\"Clients\"},\"description\":{\"ar\":\"أتمّوا صفقاتهم معنا.\",\"en\":\"Closed their deals with us.\"}},{\"number\":\"١٢٠+\",\"title\":{\"ar\":\"عقار\",\"en\":\"Properties\"},\"description\":{\"ar\":\"معروض حاليًا وبإدارتنا.\",\"en\":\"Currently listed and managed.\"}}],\"title\":\"Our Story\",\"description\":\"Alam started as a small office in Salmiya and today manages a portfolio covering all six governorates of Kuwait with a team of specialised agents. We believe a successful deal starts with honest information and a fair price.\"}}', '2026-08-09 15:19:09', '2026-08-09 15:24:35');
