('1', 'home', 'الرئيسية', '{\"ar\":\"علم العقارية | عقارات الكويت للبيع والإيجار\",\"en\":\"Alam Real Estate | Kuwait Properties for Sale and Rent\"}', '{\"ar\":\"تصفّح أحدث العقارات في الكويت: شقق وفلل وأراضٍ ومكاتب بأسعار السوق.\",\"en\":\"Browse the latest properties in Kuwait: apartments, villas, land and offices at market prices.\"}', '1', '2026-08-09 15:19:08', '2026-08-09 15:24:37', '{\"ar\":\"عقارات الكويت, شقق للإيجار, فلل للبيع\",\"en\":\"kuwait real estate, apartments for rent, villas for sale\"}'),
('2', 'about', 'من نحن', '{\"ar\":\"من نحن | علم العقارية\",\"en\":\"About Us | Alam Real Estate\"}', '{\"ar\":\"تعرّف على علم العقارية وفريقها وخبرتها في السوق الكويتي.\",\"en\":\"Learn about Alam Real Estate, its team and market experience.\"}', '1', '2026-08-09 15:19:08', '2026-08-09 15:24:37', '{\"ar\":\"شركة عقارية كويتية\",\"en\":\"kuwaiti real estate company\"}'),
('3', 'properties', 'العقارات', '{\"ar\":\"العقارات المتاحة | علم العقارية\",\"en\":\"Available Properties | Alam Real Estate\"}', '{\"ar\":\"قائمة كاملة بالعقارات المتاحة للبيع والإيجار في جميع مناطق الكويت.\",\"en\":\"A complete list of properties for sale and rent across Kuwait.\"}', '1', '2026-08-09 15:19:09', '2026-08-09 15:24:37', '{\"ar\":\"عقارات للبيع, عقارات للإيجار\",\"en\":\"properties for sale, properties for rent\"}'),
('4', 'offers', 'العروض العقارية', '{\"ar\":\"العروض العقارية | علم العقارية\",\"en\":\"Property Offers | Alam Real Estate\"}', '{\"ar\":\"أحدث العروض والخصومات على العقارات المختارة.\",\"en\":\"The latest offers and discounts on selected properties.\"}', '1', '2026-08-09 15:19:09', '2026-08-09 15:24:37', '{\"ar\":\"عروض عقارية\",\"en\":\"property offers\"}'),
('5', 'areas', 'أفضل المناطق', '{\"ar\":\"أفضل مناطق الكويت العقارية | علم العقارية\",\"en\":\"Top Areas in Kuwait | Alam Real Estate\"}', '{\"ar\":\"دليل أفضل المناطق السكنية والتجارية في الكويت.\",\"en\":\"A guide to the best residential and commercial areas in Kuwait.\"}', '1', '2026-08-09 15:19:09', '2026-08-09 15:24:37', '{\"ar\":\"مناطق الكويت, السالمية, حولي\",\"en\":\"kuwait areas, salmiya, hawally\"}'),
('6', 'contact', 'تواصل معنا', '{\"ar\":\"تواصل معنا | علم العقارية\",\"en\":\"Contact Us | Alam Real Estate\"}', '{\"ar\":\"اتصل بنا أو أرسل طلبك وسنرد خلال ساعة عمل.\",\"en\":\"Call us or send a request and we will reply within one business hour.\"}', '1', '2026-08-09 15:19:09', '2026-08-09 15:24:37', '{\"ar\":\"تواصل, رقم مكتب عقاري\",\"en\":\"contact, real estate office\"}'),
('7', 'property-details', 'تفاصيل العقار', '{\"ar\":\"تفاصيل العقار | علم العقارية\",\"en\":\"Property Details | Alam Real Estate\"}', '{\"ar\":\"كل تفاصيل العقار: الصور والمواصفات والموقع والسعر.\",\"en\":\"All property details: photos, specifications, location and price.\"}', '1', '2026-08-09 15:19:09', '2026-08-09 15:24:37', '{\"ar\":\"تفاصيل عقار\",\"en\":\"property details\"}'),
('8', 'agent', 'تفاصيل مسؤول العقار', '{\"ar\":\"مسؤول العقار | علم العقارية\",\"en\":\"Agent Profile | Alam Real Estate\"}', '{\"ar\":\"تعرّف على مسؤول العقار وعقاراته وتقييمات عملائه.\",\"en\":\"Learn about the agent, their listings and client reviews.\"}', '1', '2026-08-09 15:19:09', '2026-08-09 15:24:37', '{\"ar\":\"مسؤول عقار\",\"en\":\"real estate agent\"}'),
