('1', 'نايف الرومي', '{\"ar\":\"مستثمر عقاري\",\"en\":\"Real-estate investor\"}', '{\"ar\":\"تعاملت مع أكثر من مكتب، وفريق علم الأوضح والأسرع في إنهاء الإجراءات.\",\"en\":\"I have dealt with several offices; the Alam team is the clearest and fastest in completing procedures.\"}', '5', '0', '1', '2026-08-09 15:24:37', '2026-08-09 15:24:37'),
('2', 'عبير المهنا', '{\"ar\":\"صاحبة عمل\",\"en\":\"Business owner\"}', '{\"ar\":\"ساعدوني في إيجاد مكتب مناسب لشركتي خلال أسبوع واحد فقط.\",\"en\":\"They helped me find the right office for my company in just one week.\"}', '5', '1', '1', '2026-08-09 15:24:38', '2026-08-09 15:24:38'),
('3', 'حسين العلي', '{\"ar\":\"مستأجر\",\"en\":\"Tenant\"}', '{\"ar\":\"المعلومات كانت دقيقة تمامًا والشقة مطابقة للصور.\",\"en\":\"The information was completely accurate and the apartment matched the photos.\"}', '4', '2', '1', '2026-08-09 15:24:40', '2026-08-09 15:24:40'),
('4', 'وضحة العنزي', '{\"ar\":\"مالكة عقار\",\"en\":\"Property owner\"}', '{\"ar\":\"أجّروا شقتي خلال عشرة أيام بسعر أعلى مما توقعت.\",\"en\":\"They rented my apartment within ten days at a higher price than I expected.\"}', '5', '3', '1', '2026-08-09 15:24:41', '2026-08-09 15:24:41'),
('5', 'طلال الشمري', '{\"ar\":\"مشترٍ\",\"en\":\"Buyer\"}', '{\"ar\":\"متابعة ممتازة، وأتمنى فقط لو كانت خيارات الجهراء أكثر.\",\"en\":\"Excellent follow-up; I only wish there were more options in Jahra.\"}', '4', '4', '1', '2026-08-09 15:24:42', '2026-08-09 15:24:42');
